// Set default values
const input = $input.first().json;

// Ensure full ISO timestamps for Supabase
const formatEndDate = (d) => {
  if (!d) return new Date().toISOString().split('T')[0] + 'T23:59:59Z';
  return d.includes('T') ? d : d + 'T23:59:59Z';
};

const formatStartDate = (d) => {
  if (!d) return new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] + 'T00:00:00Z';
  return d.includes('T') ? d : d + 'T00:00:00Z';
};

return [{
  json: {
    type: input.type || 'company',
    device_id: input.device_id || null,
    start_date: formatStartDate(input.start_date),
    end_date: formatEndDate(input.end_date),
    company_name: input.company_name || 'Geral',
    device_name: input.device_name || input.device_id || 'Todos',
    device_code: input.device_code || input.device_id || '--',
    ala: input.ala || '--'
  }
}];

// Process and prepare all data for HTML Report
let html_rows = '';
let stats = {
  total_records: 0, temp_avg: '--', temp_max: '--', temp_min: '--',
  humidity_avg: '--', battery_avg: '--', voltage_avg: '--',
  device_name: 'Todos', device_code: '--', company_name: 'Geral', ala: 'Não informada',
  period: 'Período não informado', year: new Date().getFullYear(), month: ''
};

try {
  const telemetryData = $('Buscar Telemetry').all();
  const config = $('Set Defaults').first().json;

  const formatDate = (isoStr) => {
    if (!isoStr) return '';
    const d = new Date(isoStr);
    return d.toLocaleDateString('pt-BR');
  };

  stats.device_name = config.device_name || 'Todos';
  stats.device_code = config.device_code || '--';
  stats.company_name = config.company_name || 'Geral';
  stats.ala = config.ala || 'Não informada';
  stats.period = `${formatDate(config.start_date)} a ${formatDate(config.end_date)}`;
  const reportDate = config.start_date ? new Date(config.start_date) : new Date();
  stats.year = reportDate.getFullYear();
  stats.month = reportDate.toLocaleString('pt-BR', { month: 'long' });

  let data = [];
  if (telemetryData && telemetryData.length > 0) {
    data = telemetryData.map(t => t.json).sort((a,b) => new Date(a.timestamp) - new Date(b.timestamp));

    const avg = arr => arr.length ? (arr.reduce((a,b) => a + b, 0) / arr.length).toFixed(1) : '0';

    const temps = data.map(d => d.temperature).filter(v => v != null);
    const humidities = data.map(d => d.humidity).filter(v => v != null);
    const batteries = data.map(d => d.battery).filter(v => v != null);
    const voltages = data.map(d => d.voltage).filter(v => v != null);

    stats.total_records = data.length;
    stats.temp_avg = avg(temps);
    stats.temp_max = temps.length ? Math.max(...temps).toFixed(1) : '0';
    stats.temp_min = temps.length ? Math.min(...temps).toFixed(1) : '0';
    stats.humidity_avg = avg(humidities);
    stats.battery_avg = avg(batteries);
    stats.voltage_avg = avg(voltages);
  }

  // Generate HTML Rows
  const diasAgrupados = {};
  data.forEach(linha => {
    const dt = new Date(linha.timestamp);
    const dia = dt.getDate();
    if (!dia) return;

    if (!diasAgrupados[dia]) {
      diasAgrupados[dia] = { dia: dia, manhas: [], tardes: [] };
    }

    const entry = {
      HORA: dt.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
      TEMP: linha.temperature != null ? linha.temperature.toFixed(1) : '--',
      MAX: linha.temperature != null ? linha.temperature.toFixed(1) : '--',
      MIN: linha.temperature != null ? linha.temperature.toFixed(1) : '--'
    };

    if (dt.getHours() >= 12) diasAgrupados[dia].tardes.push(entry);
    else diasAgrupados[dia].manhas.push(entry);
  });

  Object.values(diasAgrupados).sort((a, b) => a.dia - b.dia).forEach(grupo => {
    const maxLen = Math.max(grupo.manhas.length, grupo.tardes.length, 1);
    for (let i = 0; i < maxLen; i++) {
      const m = grupo.manhas[i] || { HORA: '', TEMP: '', MAX: '', MIN: '' };
      const t = grupo.tardes[i] || { HORA: '', TEMP: '', MAX: '', MIN: '' };
      html_rows += '<tr>' +
        '<td style="text-align:center;">' + (i === 0 ? grupo.dia : '') + '</td>' +
        '<td>' + m.HORA + '</td><td>' + m.MAX + '</td><td>' + m.MIN + '</td><td>' + m.TEMP + '</td><td></td>' +
        '<td>' + t.HORA + '</td><td>' + t.MAX + '</td><td>' + t.MIN + '</td><td>' + t.TEMP + '</td><td></td>' +
        '<td></td>' +
        '</tr>';
    }
  });
} catch (e) {
  console.error(e);
}

return [{ json: { stats, html_rows } }];

// Format WhatsApp message
const stats = $('Processar Dados').first().json.stats;
const config = $('Set Defaults').first().json;

const message = `📊 *RELATÓRIO DE TELEMETRIA*\n\n` +
`📍 *Dispositivo(s):* ${stats.device_name}\n` +
`📅 *Período:* ${stats.period}\n` +
`📈 *Total de registros:* ${stats.total_records}\n\n` +
`*TEMPERATURA:*\n` +
`  Média: ${stats.temp_avg}°C\n` +
`  Máxima: ${stats.temp_max}°C\n` +
`  Mínima: ${stats.temp_min}°C\n\n` +
`*OUTROS DADOS:*\n` +
`  Umidade Média: ${stats.humidity_avg}%\n` +
`  Bateria Média: ${stats.battery_avg}V\n` +
`  Tensão Média: ${stats.voltage_avg}V\n\n` +
`⏰ Relatório gerado: ${new Date().toLocaleString('pt-BR')}`;

// Return message even if no recipients (for testing)
return [{ json: { message, phone: '5581999999999' } }];

const binaryData = await $input.first().binary.data.toBuffer();
const base64String = binaryData.toString('base64');

return [{
  json: {
    pdf_base64: base64String,
    fileName: 'relatorio_telemetria.pdf',
    mimeType: 'application/pdf'
  }
}];

// Build response
const stats = $('Processar Dados').first().json.stats;
const config = $('Set Defaults').first().json;
const pdf_data = $('Extract PDF').first().json;

return [{
  json: {
    status: 'success',
    message: 'Relatório processado com sucesso',
    type: config.type,
    period: { start: config.start_date, end: config.end_date },
    pdf_base64: pdf_data.pdf_base64,
    stats: {
      total_records: stats.total_records,
      temp_avg: stats.temp_avg,
      temp_max: stats.temp_max,
      temp_min: stats.temp_min
    }
  }
}];
